"""
bulwarkos_wifi — BulwarkOS WiFi management host package.

Provides the host-side daemon that bridges the sys-net VM's iwd WiFi
controller to the host desktop via a virtio-serial channel, exposing
both a native D-Bus interface (org.bulwarkos.Wifi) and a NetworkManager
compatibility shim so any desktop environment's network applet works
without modification.

Usage:
    python3 -m bulwarkos_wifi          # start the daemon
    python3 -m bulwarkos_wifi.cli      # CLI tool
    bulwark-wifi <command>             # CLI via entry point script
"""

__version__ = "0.1.0"
__author__  = "BulwarkOS"

# virtio-serial port — QEMU exposes this on the host when sys-net is running
VIRTIO_PORT = "/dev/virtio-ports/org.bulwarkos.wifi"

# D-Bus service name and object path
DBUS_NAME  = "org.bulwarkos.Wifi"
DBUS_PATH  = "/org/bulwarkos/Wifi"
DBUS_IFACE = "org.bulwarkos.Wifi"
